import { LitElement, html, nothing } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { commandGroupStyles } from './command.styles.js';

/**
 * Named group within a command palette.
 *
 * @element bl-command-group
 * @slot - `bl-command-item` elements.
 */
@customElement('bl-command-group')
export class BlCommandGroup extends LitElement {
  static override styles = [tokens, commandGroupStyles];

  /** Group heading text. */
  @property()
  heading = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'group');
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('heading') && this.heading) {
      this.setAttribute('aria-label', this.heading);
    }
  }

  protected override render() {
    return html`
      ${this.heading ? html`<div class="label" part="label">${this.heading}</div>` : nothing}
      <slot></slot>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-command-group': BlCommandGroup;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { commandInputStyles } from './command.styles.js';

/**
 * Search input for the command palette.
 *
 * @element bl-command-input
 */
@customElement('bl-command-input')
export class BlCommandInput extends LitElement {
  static override styles = [tokens, commandInputStyles];

  /** Placeholder text. */
  @property()
  placeholder = 'Type a command or search...';

  private _handleInput = (e: Event): void => {
    const value = (e.target as HTMLInputElement).value;
    this.dispatchEvent(
      new CustomEvent('bl-command-input-change', {
        detail: { value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <div class="input-wrapper">
        <svg
          class="search-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
          aria-hidden="true"
        >
          <circle cx="11" cy="11" r="8"></circle>
          <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
        </svg>
        <input
          part="input"
          type="text"
          role="combobox"
          aria-autocomplete="list"
          aria-expanded="true"
          placeholder=${this.placeholder}
          @input=${this._handleInput}
        />
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-command-input': BlCommandInput;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { commandItemStyles } from './command.styles.js';

/**
 * Individual action/result in a command palette.
 *
 * @element bl-command-item
 * @slot - Item label text.
 * @slot icon - Icon element.
 * @slot shortcut - Keyboard shortcut display.
 */
@customElement('bl-command-item')
export class BlCommandItem extends LitElement {
  static override styles = [tokens, commandItemStyles];

  /** Value identifier for this item. */
  @property()
  value = '';

  /** Whether this item is disabled. */
  @property({ type: Boolean })
  disabled = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'option');
    this.addEventListener('click', this._handleClick);
    this.addEventListener('mouseenter', this._handleMouseEnter);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('click', this._handleClick);
    this.removeEventListener('mouseenter', this._handleMouseEnter);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  /** Set highlighted state. */
  setHighlighted(highlighted: boolean): void {
    if (highlighted) {
      this.setAttribute('data-highlighted', '');
    } else {
      this.removeAttribute('data-highlighted');
    }
  }

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-command-item-click', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _handleMouseEnter = (): void => {
    if (this.disabled) return;
    // Highlight on hover
    const items = Array.from(
      this.closest('bl-command, bl-command-dialog')?.querySelectorAll<BlCommandItem>('bl-command-item') ?? [],
    );
    items.forEach((item) => item.setHighlighted(false));
    this.setHighlighted(true);
  };

  protected override render() {
    return html`
      <div class="item" part="item">
        <span class="icon"><slot name="icon"></slot></span>
        <span class="label"><slot></slot></span>
        <span class="shortcut"><slot name="shortcut"></slot></span>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-command-item': BlCommandItem;
  }
}

